import{c as r,Q as a,j as d,m as e}from"./chunks/framework.B2dUnTNU.js";const c=JSON.parse('{"title":"新机制详解","description":"","frontmatter":{},"headers":[],"relativePath":"b42/mechanics.md","filePath":"b42/mechanics.md","lastUpdated":1779619065000}'),l={name:"b42/mechanics.md"};function o(i,t,h,n,s,u){return a(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="新机制详解" tabindex="-1">新机制详解 <a class="header-anchor" href="#新机制详解" aria-label="Permalink to &quot;新机制详解&quot;">​</a></h1><p>B42 引入了大量影响日常玩法的系统级变化。本章汇总核心的新机制，每个都对 B41 玩家的习惯构成挑战。</p><hr><h2 id="💡-光照重做——真正的黑暗" tabindex="-1">💡 光照重做——真正的黑暗 <a class="header-anchor" href="#💡-光照重做——真正的黑暗" aria-label="Permalink to &quot;💡 光照重做——真正的黑暗&quot;">​</a></h2><p>B42 用全新的<strong>光线传播系统</strong>取代了 B41 的方块式房间亮度模型。</p><h3 id="b41-vs-b42" tabindex="-1">B41 vs B42 <a class="header-anchor" href="#b41-vs-b42" aria-label="Permalink to &quot;B41 vs B42&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方面</th><th>B41</th><th>B42</th></tr></thead><tbody><tr><td>光照模型</td><td>基于房间的方块亮度</td><td>光线在墙体间反弹、从门窗漏出</td></tr><tr><td>夜晚室内</td><td>灰暗但可见</td><td><strong>完全漆黑</strong></td></tr><tr><td>手电筒</td><td>可有可无</td><td><strong>必需品</strong></td></tr><tr><td>光源可见性</td><td>不影响丧尸警觉</td><td>丧尸从更远处看到光</td></tr></tbody></table><h3 id="实战影响" tabindex="-1">实战影响 <a class="header-anchor" href="#实战影响" aria-label="Permalink to &quot;实战影响&quot;">​</a></h3><ul><li>没有手电或火源进地下室 = 自杀</li><li>发电机和电池的价值大幅上升</li><li>蜡烛成为重要的应急光源</li><li>霓虹灯、路灯、火光都有真实的光影投射</li><li>夜晚感觉像真正的夜晚——&quot;令人不适的黑暗&quot;</li><li>墙上的开关会发出微弱光晕，可以利用它定位</li></ul><div class="tip custom-block"><p class="custom-block-title">适应建议</p><p>身上永远带手电 + 备用电池。进入任何未知建筑前先开灯。把发电机和燃料的优先级提上去。</p></div><hr><h2 id="💪-肌肉疲劳系统-muscle-strain" tabindex="-1">💪 肌肉疲劳系统 (Muscle Strain) <a class="header-anchor" href="#💪-肌肉疲劳系统-muscle-strain" aria-label="Permalink to &quot;💪 肌肉疲劳系统 (Muscle Strain)&quot;">​</a></h2><p>B42 最影响战斗的新机制——<strong>重武器会造成肌肉拉伤</strong>。</p><h3 id="机制说明" tabindex="-1">机制说明 <a class="header-anchor" href="#机制说明" aria-label="Permalink to &quot;机制说明&quot;">​</a></h3><ul><li>每次挥舞武器都会累积<strong>肌肉疲劳</strong></li><li>武器越重（Encumbrance 越高），疲劳积累越快</li><li>疲劳过高 → 伤害降低 → 挥速变慢 → 更危险</li><li>需要<strong>休息</strong>或<strong>换轻型武器</strong>来恢复</li></ul><h3 id="武器重量与疲劳" tabindex="-1">武器重量与疲劳 <a class="header-anchor" href="#武器重量与疲劳" aria-label="Permalink to &quot;武器重量与疲劳&quot;">​</a></h3><table tabindex="0"><thead><tr><th>武器类型</th><th>重量等级</th><th>可持续战斗时间</th></tr></thead><tbody><tr><td>短刀 (Hunting Knife)</td><td>极轻</td><td>极长</td></tr><tr><td>短棍 (Nightstick, Hammer)</td><td>轻</td><td>长</td></tr><tr><td>手斧 (Hand Axe)</td><td>中</td><td>中等</td></tr><tr><td>长棍 (Crowbar, Baseball Bat)</td><td>中重</td><td>中等偏短</td></tr><tr><td>双手斧 (Fire Axe, Wood Axe)</td><td>重</td><td>短</td></tr><tr><td>大锤 (Sledgehammer)</td><td>极重</td><td>极短</td></tr></tbody></table><h3 id="适应策略" tabindex="-1">适应策略 <a class="header-anchor" href="#适应策略" aria-label="Permalink to &quot;适应策略&quot;">​</a></h3><ol><li><strong>武器轮换</strong>：不要一把武器砍到底，准备两把不同类型的武器</li><li><strong>轻型武器有价值了</strong>：B41 时代无人问津的小刀和短棍现在有了真正的用武之地</li><li><strong>战斗节奏变慢</strong>：莽撞行为受到惩罚，更注重战术</li><li><strong>维护技能更重要</strong>：保养好的武器效率更高，能用更少挥砍解决问题</li></ol><hr><h2 id="🎣-钓鱼重做" tabindex="-1">🎣 钓鱼重做 <a class="header-anchor" href="#🎣-钓鱼重做" aria-label="Permalink to &quot;🎣 钓鱼重做&quot;">​</a></h2><p>B42 的钓鱼从&quot;对着水面点菜单&quot;变成了<strong>观察+互动</strong>的迷你游戏。</p><h3 id="变化" tabindex="-1">变化 <a class="header-anchor" href="#变化" aria-label="Permalink to &quot;变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>B41</th><th>B42</th></tr></thead><tbody><tr><td>右键水面 → 等</td><td>先观察水面找鱼群</td></tr><tr><td>固定收鱼率</td><td>鱼群位置和密度每局随机</td></tr><tr><td>无视觉反馈</td><td>水面有<strong>可见鱼花</strong>（鱼跃水面的 splash）</td></tr><tr><td>无环境影响</td><td>枪声会<strong>吓跑鱼</strong>，暂时停止咬钩</td></tr></tbody></table><h3 id="新机制" tabindex="-1">新机制 <a class="header-anchor" href="#新机制" aria-label="Permalink to &quot;新机制&quot;">​</a></h3><ul><li><strong>鱼饵系统 (Chum)</strong>：可制作碎饵撒到水中吸引鱼群</li><li>每个世界的鱼类种群分布是程序化生成的，不会背板</li><li>鱼有不同的活动区域和时间</li><li>钓鱼从被动等待变成主动寻找</li></ul><hr><h2 id="🧪-液体系统-fluid-system" tabindex="-1">🧪 液体系统 (Fluid System) <a class="header-anchor" href="#🧪-液体系统-fluid-system" aria-label="Permalink to &quot;🧪 液体系统 (Fluid System)&quot;">​</a></h2><p>B42 引入了一个统一的液体管理框架。所有液体都有属性定义。</p><h3 id="液体属性" tabindex="-1">液体属性 <a class="header-anchor" href="#液体属性" aria-label="Permalink to &quot;液体属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>Beverage / Alcoholic / Fuel / Poisonous</td></tr><tr><td>热量</td><td>每升卡路里</td></tr><tr><td>酒精度</td><td>酒精百分比</td></tr><tr><td>能量含量</td><td>燃料的能量值</td></tr></tbody></table><h3 id="混合机制" tabindex="-1">混合机制 <a class="header-anchor" href="#混合机制" aria-label="Permalink to &quot;混合机制&quot;">​</a></h3><ul><li>可以把威士忌倒进橙汁 → 稀释鸡尾酒，属性按比例计算</li><li>漂白剂混进饮料 → 可定量的中毒效果（加一点生病，加一瓶致死）</li><li>任何容器可以装任何液体</li></ul><h3 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h3><ul><li>药水饮料调制</li><li>燃料混合</li><li>Molotov 定制</li><li>汤/炖菜作为液体混合物</li><li>MOD 可自定义液体类型注册</li></ul><hr><h2 id="🎵-动态音乐" tabindex="-1">🎵 动态音乐 <a class="header-anchor" href="#🎵-动态音乐" aria-label="Permalink to &quot;🎵 动态音乐&quot;">​</a></h2><p>B42 的音乐系统从&quot;播放背景音乐&quot;升级为<strong>动态适应</strong>：</p><ul><li>探索时 → 氛围音乐</li><li>紧张时（丧尸在附近）→ 紧张主题</li><li>战斗时 → 动作主题</li><li>过渡平滑，不会突然切换</li><li>Zach Beever 原始原声+Formosa 合作多强度编曲</li></ul><hr><h2 id="🗣️-玩家语音" tabindex="-1">🗣️ 玩家语音 <a class="header-anchor" href="#🗣️-玩家语音" aria-label="Permalink to &quot;🗣️ 玩家语音&quot;">​</a></h2><p>B42 首次引入<strong>玩家角色语音</strong>：</p><ul><li>4 种男声 + 4 种女声可选</li><li>角色会咳嗽、打喷嚏、喘息、用力声</li><li>语音命令（&quot;嘿！&quot;&quot;嘘！&quot;）可用于多人交流和引开丧尸</li><li>语音也是丧尸听觉系统的一部分——喊叫会引怪</li></ul><hr><h2 id="🧟-丧尸系统变化" tabindex="-1">🧟 丧尸系统变化 <a class="header-anchor" href="#🧟-丧尸系统变化" aria-label="Permalink to &quot;🧟 丧尸系统变化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变化</th><th>说明</th></tr></thead><tbody><tr><td><strong>属性随机化</strong></td><td>每只丧尸的耐久度、听力范围、速度都有随机浮动</td></tr><tr><td><strong>新刷新热图</strong></td><td>新生成系统带噪声叠加，以前安全的地方可能变危险</td></tr><tr><td><strong>布娃娃物理</strong></td><td>爆炸和撞击有真实物理效果</td></tr><tr><td><strong>丧尸砸栅栏不再给玩家 Stress</strong></td><td>B42.16 改动——栅栏被攻击不再触发玩家焦虑</td></tr><tr><td><strong>Extinction Mode 白天跑尸</strong></td><td>灭绝模式新增白天冲刺丧尸</td></tr><tr><td><strong>持久警报</strong></td><td>汽车警报不再能通过存读档消除</td></tr></tbody></table><hr><h2 id="🧹-其他新机制" tabindex="-1">🧹 其他新机制 <a class="header-anchor" href="#🧹-其他新机制" aria-label="Permalink to &quot;🧹 其他新机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>说明</th></tr></thead><tbody><tr><td><strong>尸体拖拽</strong></td><td>可拖动尸体并扔出窗外，背后的 GrappleTech 也为未来的工作站动画打基础</td></tr><tr><td><strong>清洁系统</strong></td><td>用漂白剂和拖把清理基地墙面和地面血迹</td></tr><tr><td><strong>Discomfort Moodle</strong></td><td>新心情状态——睡硬地面、背太重、小伤会触发</td></tr><tr><td><strong>4K UI 缩放</strong></td><td>高分屏不再眼瞎</td></tr><tr><td><strong>座位/躺床动画</strong></td><td>之前需 MOD 的动作现在官方支持</td></tr><tr><td><strong>官方 MOD 管理器</strong></td><td>内置，B41 MOD 不兼容，需 B42 版本</td></tr><tr><td><strong>环境叙事</strong></td><td>数百种新物品、可读传单/报纸、注释地图、半截日记、血迹场景</td></tr></tbody></table>',49)])])}const g=r(l,[["render",o]]);export{c as __pageData,g as default};
